/**
 * Generate Richard's Developer Logs
 * Creates realistic developer logs based on git commit history
 * Emulates Richard's writing style without using actual content from samples
 */

const { getStore } = require("@netlify/blobs");

const headers = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
  "Content-Type": "application/json",
};

/**
 * Get commit history from stored data or return empty
 * Commits should be generated by a build script and stored in Blobs
 */
async function getCommitHistory(store) {
  try {
    const stored = await store.get("git-commit-history", { type: "json" });
    if (stored && stored.commits) {
      return stored.commits.map(c => ({
        hash: c.hash,
        date: new Date(c.date),
        message: c.message
      }));
    }
  } catch (error) {
    console.warn('[Developer Logs] No stored commit history:', error.message);
  }
  return [];
}

/**
 * Group commits by date (same day)
 */
function groupCommitsByDate(commits) {
  const grouped = {};
  commits.forEach(commit => {
    const dateKey = commit.date.toISOString().split('T')[0];
    if (!grouped[dateKey]) {
      grouped[dateKey] = [];
    }
    grouped[dateKey].push(commit);
  });
  return grouped;
}

/**
 * Generate a developer log entry in Richard's style
 * Emulates: direct statements, clear cause-and-effect, "absolutely valid", "pretty hard to", etc.
 * Style notes: Uses phrases like "absolutely", "pretty hard to", "one of the biggest", "Unlike X, Y was able to"
 */
function generateLogEntry(commits, date) {
  const dateObj = new Date(date);
  const formattedDate = dateObj.toLocaleDateString('en-US', { 
    weekday: 'long', 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });
  
  // Analyze commits to understand what was done
  const commitMessages = commits.map(c => c.message.toLowerCase());
  const allText = commitMessages.join(' ');
  
  // Determine the main theme and extract key terms
  let theme = 'general updates';
  let tone = 'matter-of-fact';
  let keyTerms = [];
  
  if (allText.includes('fix') || allText.includes('bug') || allText.includes('error') || allText.includes('issue')) {
    theme = 'fixing issues';
    tone = 'problem-solving';
    keyTerms = commitMessages.filter(m => m.includes('fix') || m.includes('bug') || m.includes('error'));
  } else if (allText.includes('feat') || allText.includes('add') || allText.includes('implement') || allText.includes('create')) {
    theme = 'building features';
    tone = 'excited';
    keyTerms = commitMessages.filter(m => m.includes('feat') || m.includes('add') || m.includes('implement'));
  } else if (allText.includes('security') || allText.includes('xss') || allText.includes('vulnerability') || allText.includes('prevent')) {
    theme = 'security improvements';
    tone = 'serious';
    keyTerms = commitMessages.filter(m => m.includes('security') || m.includes('xss') || m.includes('vulnerability'));
  } else if (allText.includes('deploy') || allText.includes('migration') || allText.includes('build')) {
    theme = 'deployment work';
    tone = 'focused';
    keyTerms = commitMessages.filter(m => m.includes('deploy') || m.includes('migration'));
  }
  
  // Generate log text in Richard's style
  // Style characteristics: direct, clear, uses "absolutely", "pretty hard to", "one of the biggest", "Unlike X, Y"
  let logText = '';
  
  if (commits.length === 1) {
    const commit = commits[0];
    const mainAction = commit.message.split(':')[0] || commit.message.split(' ')[0];
    
    logText = `Focused on ${theme} today. ${commit.message.charAt(0).toUpperCase() + commit.message.slice(1)}. `;
    
    if (tone === 'problem-solving') {
      logText += `It's pretty hard to call a system reliable when these kinds of issues keep appearing, so I made sure to address this one thoroughly and prevent it from happening again.`;
    } else if (tone === 'excited') {
      logText += `This is absolutely one of the most important additions to the platform, and I'm excited to see how it improves the user experience. The work is paying off.`;
    } else if (tone === 'serious') {
      logText += `Security is non-negotiable, and this was one of the biggest priorities for today. Can't have vulnerabilities in production - these changes directly address potential issues.`;
    } else {
      logText += `The work is progressing well, and each update brings us closer to a more robust and capable platform.`;
    }
  } else {
    logText = `Worked on ${commits.length} different updates today, all focused on ${theme}. `;
    
    const mainCommit = commits[commits.length - 1];
    const otherCommits = commits.slice(0, -1);
    
    logText += `The most significant change was ${mainCommit.message.toLowerCase()}. `;
    
    if (otherCommits.length > 0) {
      logText += `Along with that, I also ${otherCommits.slice(0, 2).map(c => c.message.toLowerCase()).join(' and ')}. `;
    }
    
    if (tone === 'problem-solving') {
      logText += `Unlike previous attempts where issues would resurface, this time I made sure to address the root cause. It's pretty hard to maintain a system when you're constantly putting out fires, so I took a more systematic approach that should prevent these problems from coming back.`;
    } else if (tone === 'excited') {
      logText += `This is absolutely one of the key improvements that will make a real difference for users. The platform is becoming more capable with each update, and these changes expand what we can offer.`;
    } else if (tone === 'serious') {
      logText += `Security can't be an afterthought. These changes directly address potential vulnerabilities, and that's one of the biggest priorities right now. Can't have these kinds of risks in production.`;
    } else if (tone === 'focused') {
      logText += `Deployment work requires attention to detail. Each of these updates needs to work together, and I made sure everything is properly configured and tested before going live.`;
    } else {
      logText += `Each of these updates contributes to a more stable and feature-rich platform. The work is paying off, and the system is becoming more robust with every change.`;
    }
  }
  
  return {
    date: formattedDate,
    timestamp: dateObj.toISOString(),
    entry: logText,
    commitCount: commits.length,
    commits: commits.map(c => ({ hash: c.hash, message: c.message }))
  };
}

/**
 * Generate all developer logs
 */
async function generateAllLogs(store) {
  const commits = await getCommitHistory(store);
  if (commits.length === 0) {
    return [];
  }
  
  const grouped = groupCommitsByDate(commits);
  const logs = [];
  
  // Generate logs for each day with commits
  Object.keys(grouped).sort().forEach(date => {
    const dayCommits = grouped[date];
    const log = generateLogEntry(dayCommits, date);
    logs.push(log);
  });
  
  return logs;
}

exports.handler = async (event, context) => {
  // CORS preflight
  if (event.httpMethod === "OPTIONS") {
    return { statusCode: 204, headers, body: "" };
  }

  try {
    // Check if we should use cached logs
    const useCache = event.queryStringParameters?.cache !== 'false';
    
    if (useCache) {
      try {
        const siteID = process.env.NETLIFY_SITE_ID || event.headers['x-nf-site-id'];
        const token = process.env.NETLIFY_BLOB_READ_WRITE_TOKEN || event.headers['x-nf-token'];
        
        let store;
        if (siteID && token) {
          store = getStore({
            name: "config",
            siteID: siteID,
            token: token,
          });
        } else {
          store = getStore({ name: "config" });
        }
        
        const cached = await store.get("developer-logs", { type: "json" });
        if (cached && cached.timestamp) {
          const cacheAge = Date.now() - new Date(cached.timestamp).getTime();
          // Cache for 1 hour
          if (cacheAge < 60 * 60 * 1000) {
            console.log('[Developer Logs] Returning cached logs');
            return {
              statusCode: 200,
              headers,
              body: JSON.stringify(cached.logs),
            };
          }
        }
      } catch (cacheError) {
        console.warn('[Developer Logs] Cache check failed, generating fresh:', cacheError.message);
      }
    }
    
    // Get store for commit history
    const siteID = process.env.NETLIFY_SITE_ID || event.headers['x-nf-site-id'];
    const token = process.env.NETLIFY_BLOB_READ_WRITE_TOKEN || event.headers['x-nf-token'];
    
    let store;
    if (siteID && token) {
      store = getStore({
        name: "config",
        siteID: siteID,
        token: token,
      });
    } else {
      store = getStore({ name: "config" });
    }
    
    // Generate logs
    console.log('[Developer Logs] Generating developer logs from git history...');
    const logs = await generateAllLogs(store);
    
    // Cache the results
    try {
      await store.set("developer-logs", JSON.stringify({
        logs: logs,
        timestamp: new Date().toISOString()
      }));
    } catch (cacheError) {
      console.warn('[Developer Logs] Failed to cache logs:', cacheError.message);
    }
    
    return {
      statusCode: 200,
      headers,
      body: JSON.stringify(logs),
    };
    
  } catch (error) {
    console.error('[Developer Logs] Error:', error);
    return {
      statusCode: 500,
      headers,
      body: JSON.stringify({
        error: "Failed to generate developer logs",
        message: error.message
      }),
    };
  }
};

